-- Barberium v12.3 — Produtos, estoque, venda interna e comissões de produtos

create table if not exists public.products (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null references public.barbershops(id) on delete cascade,
  name text not null,
  category text,
  description text,
  sku text,
  barcode text,
  image_path text,
  cost_cents integer not null default 0 check (cost_cents >= 0),
  price_cents integer not null default 0 check (price_cents >= 0),
  min_stock integer not null default 0 check (min_stock >= 0),
  is_active boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists products_barbershop_sku_key on public.products(barbershop_id,sku) where sku is not null and btrim(sku)<>'';
create unique index if not exists products_barbershop_barcode_key on public.products(barbershop_id,barcode) where barcode is not null and btrim(barcode)<>'';
create index if not exists products_barbershop_active_idx on public.products(barbershop_id,is_active,sort_order,name);
alter table public.products enable row level security;

create table if not exists public.product_inventory (
  product_id uuid not null references public.products(id) on delete cascade,
  unit_id uuid not null references public.units(id) on delete cascade,
  barbershop_id uuid not null references public.barbershops(id) on delete cascade,
  quantity integer not null default 0 check (quantity >= 0),
  updated_at timestamptz not null default now(),
  primary key(product_id,unit_id)
);
create index if not exists product_inventory_unit_idx on public.product_inventory(unit_id,quantity);
alter table public.product_inventory enable row level security;

create table if not exists public.product_stock_movements (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null references public.barbershops(id) on delete cascade,
  unit_id uuid not null references public.units(id) on delete restrict,
  product_id uuid not null references public.products(id) on delete restrict,
  movement_type text not null check (movement_type in ('opening','purchase','adjustment','loss','sale','sale_return','refund')),
  quantity_delta integer not null check (quantity_delta <> 0),
  quantity_before integer not null check (quantity_before >= 0),
  quantity_after integer not null check (quantity_after >= 0),
  unit_cost_cents integer check (unit_cost_cents is null or unit_cost_cents >= 0),
  reference_type text,
  reference_id uuid,
  reason text,
  actor_member_id uuid references public.barbershop_members(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists product_stock_movements_lookup_idx on public.product_stock_movements(product_id,unit_id,created_at desc);
alter table public.product_stock_movements enable row level security;

create table if not exists public.product_commission_profiles (
  professional_id uuid primary key references public.professionals(id) on delete cascade,
  barbershop_id uuid not null references public.barbershops(id) on delete cascade,
  default_percent numeric(7,4) not null default 0 check (default_percent between 0 and 100),
  updated_at timestamptz not null default now()
);
alter table public.product_commission_profiles enable row level security;

create table if not exists public.product_commission_rules (
  id uuid primary key default gen_random_uuid(),
  professional_id uuid not null references public.professionals(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete cascade,
  percent numeric(7,4) not null check (percent between 0 and 100),
  updated_at timestamptz not null default now(),
  unique(professional_id,product_id)
);
alter table public.product_commission_rules enable row level security;

create table if not exists public.product_sales (
  id uuid primary key default gen_random_uuid(),
  barbershop_id uuid not null references public.barbershops(id) on delete cascade,
  unit_id uuid not null references public.units(id) on delete restrict,
  customer_id uuid references public.customers(id) on delete set null,
  appointment_id uuid unique references public.appointments(id) on delete set null,
  seller_professional_id uuid references public.professionals(id) on delete set null,
  status text not null default 'draft' check (status in ('draft','completed','refunded','cancelled')),
  subtotal_cents integer not null default 0 check (subtotal_cents >= 0),
  total_cents integer not null default 0 check (total_cents >= 0),
  cost_total_cents integer not null default 0 check (cost_total_cents >= 0),
  paid_cents integer not null default 0 check (paid_cents >= 0),
  pending_cents integer not null default 0 check (pending_cents >= 0),
  note text,
  created_by_member_id uuid references public.barbershop_members(id) on delete set null,
  completed_by_member_id uuid references public.barbershop_members(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  completed_at timestamptz,
  refunded_at timestamptz
);
create index if not exists product_sales_barbershop_date_idx on public.product_sales(barbershop_id,completed_at desc);
create index if not exists product_sales_customer_idx on public.product_sales(customer_id,completed_at desc);
create index if not exists product_sales_seller_idx on public.product_sales(seller_professional_id,completed_at desc);
alter table public.product_sales enable row level security;

create table if not exists public.product_sale_items (
  id uuid primary key default gen_random_uuid(),
  sale_id uuid not null references public.product_sales(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete restrict,
  product_name_snapshot text not null,
  sku_snapshot text,
  quantity integer not null check (quantity > 0),
  unit_price_cents integer not null check (unit_price_cents >= 0),
  unit_cost_cents integer not null default 0 check (unit_cost_cents >= 0),
  line_total_cents integer not null check (line_total_cents >= 0),
  commission_percent numeric(7,4),
  commission_cents integer not null default 0,
  created_at timestamptz not null default now()
);
create index if not exists product_sale_items_sale_idx on public.product_sale_items(sale_id);
create index if not exists product_sale_items_product_idx on public.product_sale_items(product_id);
alter table public.product_sale_items enable row level security;

create table if not exists public.product_sale_payments (
  id uuid primary key default gen_random_uuid(),
  sale_id uuid not null references public.product_sales(id) on delete cascade,
  barbershop_id uuid not null references public.barbershops(id) on delete cascade,
  unit_id uuid not null references public.units(id) on delete restrict,
  method text not null check (method in ('pix','cash','debit','credit')),
  amount_cents integer not null check (amount_cents > 0),
  tendered_cents integer,
  change_cents integer not null default 0 check (change_cents >= 0),
  provider_id uuid references public.payment_providers(id) on delete set null,
  installments integer check (installments is null or installments >= 1),
  fee_cents integer not null default 0 check (fee_cents >= 0),
  received_at timestamptz not null default now(),
  actor_member_id uuid references public.barbershop_members(id) on delete set null,
  note text,
  created_at timestamptz not null default now()
);
create index if not exists product_sale_payments_sale_idx on public.product_sale_payments(sale_id,received_at);
create index if not exists product_sale_payments_finance_idx on public.product_sale_payments(barbershop_id,unit_id,received_at);
alter table public.product_sale_payments enable row level security;

create table if not exists public.product_sale_receivables (
  id uuid primary key default gen_random_uuid(),
  sale_id uuid not null unique references public.product_sales(id) on delete cascade,
  barbershop_id uuid not null references public.barbershops(id) on delete cascade,
  unit_id uuid not null references public.units(id) on delete restrict,
  original_due_cents integer not null check (original_due_cents > 0),
  paid_cents integer not null default 0 check (paid_cents >= 0),
  status text not null default 'open' check (status in ('open','partial','paid','cancelled')),
  due_date date,
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists product_sale_receivables_status_idx on public.product_sale_receivables(barbershop_id,status,due_date);
alter table public.product_sale_receivables enable row level security;

alter table public.finance_refunds add column if not exists product_sale_id uuid references public.product_sales(id) on delete set null;
create index if not exists finance_refunds_product_sale_idx on public.finance_refunds(product_sale_id) where product_sale_id is not null;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
select 'barberium-product-images','barberium-product-images',true,5242880,array['image/jpeg','image/png','image/webp']::text[]
where not exists(select 1 from storage.buckets where id='barberium-product-images');
drop policy if exists "barberium_product_images_insert" on storage.objects;
drop policy if exists "barberium_product_images_update" on storage.objects;
drop policy if exists "barberium_product_images_delete" on storage.objects;
create policy "barberium_product_images_insert" on storage.objects for insert to authenticated with check (bucket_id='barberium-product-images' and exists(select 1 from barberium.staff_membership() m where m.role in ('owner','admin') and split_part(name,'/',1)=m.barbershop_id::text));
create policy "barberium_product_images_update" on storage.objects for update to authenticated using (bucket_id='barberium-product-images' and exists(select 1 from barberium.staff_membership() m where m.role in ('owner','admin') and split_part(name,'/',1)=m.barbershop_id::text)) with check (bucket_id='barberium-product-images' and exists(select 1 from barberium.staff_membership() m where m.role in ('owner','admin') and split_part(name,'/',1)=m.barbershop_id::text));
create policy "barberium_product_images_delete" on storage.objects for delete to authenticated using (bucket_id='barberium-product-images' and exists(select 1 from barberium.staff_membership() m where m.role in ('owner','admin') and split_part(name,'/',1)=m.barbershop_id::text));

create or replace function barberium.product_commission_percent(p_professional_id uuid,p_product_id uuid) returns numeric language sql stable security definer set search_path='public','barberium','pg_temp' as $$ select coalesce((select r.percent from public.product_commission_rules r where r.professional_id=p_professional_id and r.product_id=p_product_id),(select p.default_percent from public.product_commission_profiles p where p.professional_id=p_professional_id),0) $$;

create or replace function barberium.apply_product_stock_change(p_product_id uuid,p_unit_id uuid,p_delta integer,p_movement_type text,p_reason text default null,p_reference_type text default null,p_reference_id uuid default null,p_actor_member_id uuid default null,p_unit_cost_cents integer default null) returns integer language plpgsql security definer set search_path='public','barberium','pg_temp' as $$ declare v_product record; v_unit record; v_before integer; v_after integer; begin if p_delta=0 then raise exception 'A movimentação de estoque não pode ser zero'; end if; if p_movement_type not in ('opening','purchase','adjustment','loss','sale','sale_return','refund') then raise exception 'Tipo de movimentação inválido'; end if; select id,barbershop_id,cost_cents into v_product from public.products where id=p_product_id; if v_product.id is null then raise exception 'Produto inválido'; end if; select id,barbershop_id into v_unit from public.units where id=p_unit_id; if v_unit.id is null or v_unit.barbershop_id<>v_product.barbershop_id then raise exception 'Unidade inválida'; end if; insert into public.product_inventory(product_id,unit_id,barbershop_id,quantity) values(p_product_id,p_unit_id,v_product.barbershop_id,0) on conflict(product_id,unit_id) do nothing; select quantity into v_before from public.product_inventory where product_id=p_product_id and unit_id=p_unit_id for update; v_after:=v_before+p_delta; if v_after<0 then raise exception 'Estoque insuficiente'; end if; update public.product_inventory set quantity=v_after,updated_at=now() where product_id=p_product_id and unit_id=p_unit_id; insert into public.product_stock_movements(barbershop_id,unit_id,product_id,movement_type,quantity_delta,quantity_before,quantity_after,unit_cost_cents,reference_type,reference_id,reason,actor_member_id) values(v_product.barbershop_id,p_unit_id,p_product_id,p_movement_type,p_delta,v_before,v_after,coalesce(p_unit_cost_cents,v_product.cost_cents),p_reference_type,p_reference_id,nullif(btrim(coalesce(p_reason,'')),''),p_actor_member_id); return v_after; end $$;
revoke all on function barberium.apply_product_stock_change(uuid,uuid,integer,text,text,text,uuid,uuid,integer) from public,anon,authenticated;
revoke all on function barberium.product_commission_percent(uuid,uuid) from public,anon; grant execute on function barberium.product_commission_percent(uuid,uuid) to authenticated,service_role;

create or replace function public.barberium_staff_products(p_unit_id uuid default null,p_query text default null,p_include_inactive boolean default false) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; perms jsonb; v_unit uuid; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Sem acesso'; end if; perms:=case when m.role in ('owner','admin') then barberium.default_barber_permissions() else barberium.effective_permissions(m.professional_id) end; if m.role='barber' and not (barberium.permission_enabled(perms,'sell_products') or barberium.permission_enabled(perms,'view_product_stock')) then raise exception 'Sem permissão para produtos'; end if; if p_unit_id is null then if m.role='barber' then select unit_id into v_unit from public.professionals where id=m.professional_id; else select id into v_unit from public.units where barbershop_id=m.barbershop_id and is_active order by created_at limit 1; end if; else v_unit:=p_unit_id; end if; if not exists(select 1 from public.units where id=v_unit and barbershop_id=m.barbershop_id) then raise exception 'Unidade inválida'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'category',p.category,'description',p.description,'sku',p.sku,'barcode',p.barcode,'image_path',p.image_path,'cost_cents',case when m.role in ('owner','admin') then p.cost_cents else null end,'price_cents',p.price_cents,'min_stock',p.min_stock,'is_active',p.is_active,'sort_order',p.sort_order,'quantity',coalesce(i.quantity,0),'low_stock',(coalesce(i.quantity,0)<=p.min_stock),'default_commission_hint',case when m.professional_id is not null then barberium.product_commission_percent(m.professional_id,p.id) else null end) order by p.sort_order,p.name) from public.products p left join public.product_inventory i on i.product_id=p.id and i.unit_id=v_unit where p.barbershop_id=m.barbershop_id and (p_include_inactive or p.is_active) and (nullif(btrim(coalesce(p_query,'')),'') is null or p.name ilike '%'||p_query||'%' or coalesce(p.sku,'') ilike '%'||p_query||'%' or coalesce(p.barcode,'') ilike '%'||p_query||'%' or coalesce(p.category,'') ilike '%'||p_query||'%')),'[]'::jsonb); end $$;

create or replace function public.barberium_staff_save_product(p_product_id uuid,p_name text,p_category text,p_description text,p_sku text,p_barcode text,p_image_path text,p_cost_cents integer,p_price_cents integer,p_min_stock integer,p_is_active boolean,p_sort_order integer default 0) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; v_id uuid; v_created boolean:=false; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null or m.role not in ('owner','admin') then raise exception 'Acesso somente para ADM'; end if; if length(btrim(coalesce(p_name,'')))<2 then raise exception 'Nome do produto inválido'; end if; if coalesce(p_cost_cents,0)<0 or coalesce(p_price_cents,0)<0 or coalesce(p_min_stock,0)<0 then raise exception 'Valores inválidos'; end if; if p_product_id is null then insert into public.products(barbershop_id,name,category,description,sku,barcode,image_path,cost_cents,price_cents,min_stock,is_active,sort_order) values(m.barbershop_id,btrim(p_name),nullif(btrim(coalesce(p_category,'')),''),nullif(btrim(coalesce(p_description,'')),''),nullif(btrim(coalesce(p_sku,'')),''),nullif(btrim(coalesce(p_barcode,'')),''),nullif(btrim(coalesce(p_image_path,'')),''),coalesce(p_cost_cents,0),coalesce(p_price_cents,0),coalesce(p_min_stock,0),coalesce(p_is_active,true),coalesce(p_sort_order,0)) returning id into v_id; v_created:=true; else select id into v_id from public.products where id=p_product_id and barbershop_id=m.barbershop_id; if v_id is null then raise exception 'Produto inválido'; end if; update public.products set name=btrim(p_name),category=nullif(btrim(coalesce(p_category,'')),''),description=nullif(btrim(coalesce(p_description,'')),''),sku=nullif(btrim(coalesce(p_sku,'')),''),barcode=nullif(btrim(coalesce(p_barcode,'')),''),image_path=nullif(btrim(coalesce(p_image_path,'')),''),cost_cents=coalesce(p_cost_cents,0),price_cents=coalesce(p_price_cents,0),min_stock=coalesce(p_min_stock,0),is_active=coalesce(p_is_active,true),sort_order=coalesce(p_sort_order,0),updated_at=now() where id=v_id; end if; return jsonb_build_object('ok',true,'product_id',v_id,'created',v_created); exception when unique_violation then raise exception 'SKU ou código de barras já cadastrado'; end $$;

create or replace function public.barberium_staff_adjust_product_stock(p_product_id uuid,p_unit_id uuid,p_quantity_delta integer,p_movement_type text,p_reason text default null,p_unit_cost_cents integer default null) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; v_after integer; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null or m.role not in ('owner','admin') then raise exception 'Acesso somente para ADM'; end if; if not exists(select 1 from public.products where id=p_product_id and barbershop_id=m.barbershop_id) then raise exception 'Produto inválido'; end if; if not exists(select 1 from public.units where id=p_unit_id and barbershop_id=m.barbershop_id) then raise exception 'Unidade inválida'; end if; if p_movement_type not in ('opening','purchase','adjustment','loss') then raise exception 'Tipo de movimentação inválido'; end if; if p_movement_type in ('opening','purchase') and p_quantity_delta<=0 then raise exception 'A entrada deve ser positiva'; end if; if p_movement_type='loss' and p_quantity_delta>=0 then raise exception 'Perda deve reduzir o estoque'; end if; if p_quantity_delta=0 then raise exception 'Informe uma quantidade diferente de zero'; end if; if p_movement_type in ('adjustment','loss') and btrim(coalesce(p_reason,''))='' then raise exception 'Informe o motivo do ajuste'; end if; v_after:=barberium.apply_product_stock_change(p_product_id,p_unit_id,p_quantity_delta,p_movement_type,p_reason,null,null,m.member_id,p_unit_cost_cents); if p_movement_type='purchase' and p_unit_cost_cents is not null and p_unit_cost_cents>=0 then update public.products set cost_cents=p_unit_cost_cents,updated_at=now() where id=p_product_id; end if; return jsonb_build_object('ok',true,'quantity',v_after); end $$;

create or replace function public.barberium_staff_product_stock_history(p_product_id uuid,p_unit_id uuid,p_limit integer default 100) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Sem acesso'; end if; if not exists(select 1 from public.products where id=p_product_id and barbershop_id=m.barbershop_id) then raise exception 'Produto inválido'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'movement_type',x.movement_type,'quantity_delta',x.quantity_delta,'quantity_before',x.quantity_before,'quantity_after',x.quantity_after,'unit_cost_cents',case when m.role in ('owner','admin') then x.unit_cost_cents else null end,'reason',x.reason,'reference_type',x.reference_type,'created_at',x.created_at,'actor',coalesce(pr.name,au.email,'Sistema')) order by x.created_at desc) from (select * from public.product_stock_movements where product_id=p_product_id and unit_id=p_unit_id order by created_at desc limit greatest(1,least(coalesce(p_limit,100),300))) x left join public.barbershop_members bm on bm.id=x.actor_member_id left join public.professionals pr on pr.id=bm.professional_id left join auth.users au on au.id=bm.auth_user_id),'[]'::jsonb); end $$;

create or replace function public.barberium_staff_product_commission_config() returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null or m.role not in ('owner','admin') then raise exception 'Acesso somente para ADM'; end if; return jsonb_build_object('professionals',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'unit_id',p.unit_id,'default_percent',coalesce(cp.default_percent,0),'overrides',coalesce((select jsonb_agg(jsonb_build_object('product_id',r.product_id,'percent',r.percent)) from public.product_commission_rules r join public.products x on x.id=r.product_id where r.professional_id=p.id and x.barbershop_id=m.barbershop_id),'[]'::jsonb)) order by p.sort_order,p.name) from public.professionals p left join public.product_commission_profiles cp on cp.professional_id=p.id where p.barbershop_id=m.barbershop_id and p.is_active),'[]'::jsonb),'products',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'category',x.category,'price_cents',x.price_cents) order by x.sort_order,x.name) from public.products x where x.barbershop_id=m.barbershop_id and x.is_active),'[]'::jsonb)); end $$;

create or replace function public.barberium_staff_save_product_commission_config(p_professional_id uuid,p_default_percent numeric,p_overrides jsonb default '[]'::jsonb) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; r jsonb; v_product uuid; v_percent numeric; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null or m.role not in ('owner','admin') then raise exception 'Acesso somente para ADM'; end if; if not exists(select 1 from public.professionals where id=p_professional_id and barbershop_id=m.barbershop_id) then raise exception 'Profissional inválido'; end if; if coalesce(p_default_percent,0)<0 or coalesce(p_default_percent,0)>100 then raise exception 'Percentual padrão inválido'; end if; insert into public.product_commission_profiles(professional_id,barbershop_id,default_percent) values(p_professional_id,m.barbershop_id,coalesce(p_default_percent,0)) on conflict(professional_id) do update set default_percent=excluded.default_percent,updated_at=now(); delete from public.product_commission_rules where professional_id=p_professional_id; for r in select * from jsonb_array_elements(coalesce(p_overrides,'[]'::jsonb)) loop v_product:=nullif(r->>'product_id','')::uuid; v_percent:=nullif(r->>'percent','')::numeric; if v_product is not null and v_percent is not null then if v_percent<0 or v_percent>100 then raise exception 'Percentual personalizado inválido'; end if; if not exists(select 1 from public.products where id=v_product and barbershop_id=m.barbershop_id) then raise exception 'Produto inválido'; end if; insert into public.product_commission_rules(professional_id,product_id,percent) values(p_professional_id,v_product,v_percent); end if; end loop; return jsonb_build_object('ok',true); end $$;

create or replace function public.barberium_staff_appointment_products(p_appointment_id uuid) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; a record; s record; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Sem acesso'; end if; select * into a from public.appointments where id=p_appointment_id and barbershop_id=m.barbershop_id; if a.id is null then raise exception 'Atendimento inválido'; end if; if m.role='barber' and a.professional_id<>m.professional_id then raise exception 'Sem permissão'; end if; select * into s from public.product_sales where appointment_id=a.id order by created_at desc limit 1; if s.id is null then return jsonb_build_object('sale_id',null,'status','draft','seller_professional_id',a.professional_id,'items','[]'::jsonb,'total_cents',0); end if; return jsonb_build_object('sale_id',s.id,'status',s.status,'seller_professional_id',s.seller_professional_id,'total_cents',s.total_cents,'paid_cents',s.paid_cents,'pending_cents',s.pending_cents,'completed_at',s.completed_at,'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'product_id',i.product_id,'name',i.product_name_snapshot,'sku',i.sku_snapshot,'quantity',i.quantity,'unit_price_cents',i.unit_price_cents,'line_total_cents',i.line_total_cents,'commission_percent',i.commission_percent,'commission_cents',i.commission_cents) order by i.created_at) from public.product_sale_items i where i.sale_id=s.id),'[]'::jsonb)); end $$;

create or replace function public.barberium_staff_set_appointment_products(p_appointment_id uuid,p_seller_professional_id uuid,p_items jsonb) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; perms jsonb; a record; sale record; r jsonb; pr uuid; prod record; qty integer; subtotal integer:=0; v_count integer:=0; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Sem acesso'; end if; perms:=case when m.role in ('owner','admin') then barberium.default_barber_permissions() else barberium.effective_permissions(m.professional_id) end; if m.role='barber' and not barberium.permission_enabled(perms,'sell_products') then raise exception 'Sem permissão para vender produtos'; end if; select * into a from public.appointments where id=p_appointment_id and barbershop_id=m.barbershop_id for update; if a.id is null or a.status<>'confirmed' then raise exception 'Atendimento não está disponível para adicionar produtos'; end if; if m.role='barber' and a.professional_id<>m.professional_id then raise exception 'Sem permissão'; end if; pr:=case when m.role='barber' then m.professional_id else coalesce(p_seller_professional_id,a.professional_id) end; if pr is not null and not exists(select 1 from public.professionals where id=pr and barbershop_id=m.barbershop_id and unit_id=a.unit_id and is_active) then raise exception 'Profissional responsável inválido'; end if; select * into sale from public.product_sales where appointment_id=a.id for update; if sale.id is not null and sale.status<>'draft' then raise exception 'A venda de produtos deste atendimento já foi finalizada'; end if; if jsonb_array_length(coalesce(p_items,'[]'::jsonb))=0 then if sale.id is not null then delete from public.product_sales where id=sale.id; end if; return jsonb_build_object('ok',true,'sale_id',null,'total_cents',0,'items',0); end if; if sale.id is null then insert into public.product_sales(barbershop_id,unit_id,customer_id,appointment_id,seller_professional_id,status,created_by_member_id) values(m.barbershop_id,a.unit_id,a.customer_id,a.id,pr,'draft',m.member_id) returning * into sale; else update public.product_sales set seller_professional_id=pr,customer_id=a.customer_id,updated_at=now() where id=sale.id returning * into sale; delete from public.product_sale_items where sale_id=sale.id; end if; for r in select * from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop qty:=coalesce((r->>'quantity')::int,0); if qty<=0 then continue; end if; select * into prod from public.products where id=(r->>'product_id')::uuid and barbershop_id=m.barbershop_id and is_active; if prod.id is null then raise exception 'Produto inválido'; end if; if qty>coalesce((select quantity from public.product_inventory where product_id=prod.id and unit_id=a.unit_id),0) then raise exception 'Estoque insuficiente para %',prod.name; end if; insert into public.product_sale_items(sale_id,product_id,product_name_snapshot,sku_snapshot,quantity,unit_price_cents,unit_cost_cents,line_total_cents) values(sale.id,prod.id,prod.name,prod.sku,qty,prod.price_cents,prod.cost_cents,prod.price_cents*qty); subtotal:=subtotal+prod.price_cents*qty; v_count:=v_count+qty; end loop; if subtotal<=0 then raise exception 'Selecione ao menos um produto'; end if; update public.product_sales set subtotal_cents=subtotal,total_cents=subtotal,cost_total_cents=(select coalesce(sum(quantity*unit_cost_cents),0) from public.product_sale_items where sale_id=sale.id),updated_at=now() where id=sale.id; return jsonb_build_object('ok',true,'sale_id',sale.id,'total_cents',subtotal,'items',v_count); end $$;

create or replace function barberium.complete_product_sale_core(p_sale_id uuid,p_payments jsonb,p_pending_cents integer,p_due_date date,p_note text,p_actor_member_id uuid) returns jsonb language plpgsql security definer set search_path='public','barberium','pg_temp' as $$ declare s record; i record; pay jsonb; pct numeric; comm integer; total integer; cost_total integer; paid integer:=0; amount integer; meth text; provider uuid; inst integer; fee integer; tender integer; chg integer; v_session uuid; begin select * into s from public.product_sales where id=p_sale_id for update; if s.id is null or s.status<>'draft' then raise exception 'Venda de produtos inválida'; end if; select coalesce(sum(line_total_cents),0),coalesce(sum(quantity*unit_cost_cents),0) into total,cost_total from public.product_sale_items where sale_id=s.id; if total<=0 then raise exception 'Venda sem produtos'; end if; if coalesce(p_pending_cents,0)<0 then raise exception 'Pendência inválida'; end if; for i in select * from public.product_sale_items where sale_id=s.id order by created_at loop perform barberium.apply_product_stock_change(i.product_id,s.unit_id,-i.quantity,'sale','Venda de produto','product_sale',s.id,p_actor_member_id,i.unit_cost_cents); pct:=case when s.seller_professional_id is null then 0 else barberium.product_commission_percent(s.seller_professional_id,i.product_id) end; comm:=round(i.line_total_cents*(coalesce(pct,0)/100.0))::int; update public.product_sale_items set commission_percent=pct,commission_cents=comm where id=i.id; if comm<>0 then insert into public.commission_entries(barbershop_id,unit_id,professional_id,appointment_id,source_type,source_id,description,base_cents,rate_percent,amount_cents) values(s.barbershop_id,s.unit_id,s.seller_professional_id,s.appointment_id,'product_sale',i.id,'Comissão de produto • '||i.product_name_snapshot,i.line_total_cents,pct,comm); end if; end loop; for pay in select * from jsonb_array_elements(coalesce(p_payments,'[]'::jsonb)) loop meth:=pay->>'method'; amount:=coalesce((pay->>'amount_cents')::int,0); if meth not in ('pix','cash','debit','credit') or amount<=0 then raise exception 'Pagamento inválido'; end if; provider:=nullif(pay->>'provider_id','')::uuid; inst:=coalesce(nullif(pay->>'installments','')::int,1); tender:=case when meth='cash' then coalesce(nullif(pay->>'tendered_cents','')::int,amount) else amount end; if meth='cash' and tender<amount then raise exception 'Valor recebido em dinheiro inválido'; end if; chg:=case when meth='cash' then greatest(0,tender-amount) else 0 end; fee:=case when pay ? 'fee_cents' then greatest(0,coalesce((pay->>'fee_cents')::int,0)) else barberium.payment_fee_cents(provider,meth,inst,amount) end; insert into public.product_sale_payments(sale_id,barbershop_id,unit_id,method,amount_cents,tendered_cents,change_cents,provider_id,installments,fee_cents,actor_member_id,note) values(s.id,s.barbershop_id,s.unit_id,meth,amount,case when meth='cash' then tender end,chg,provider,case when meth='credit' then inst end,fee,p_actor_member_id,pay->>'note'); if meth='cash' then select id into v_session from public.cash_sessions where unit_id=s.unit_id and barbershop_id=s.barbershop_id and status='open' order by opened_at desc limit 1; if v_session is not null then insert into public.cash_movements(cash_session_id,barbershop_id,unit_id,movement_type,amount_cents,reference_type,reference_id,note,actor_member_id) values(v_session,s.barbershop_id,s.unit_id,'payment',amount,'product_sale',s.id,'Recebimento de produtos',p_actor_member_id); end if; end if; paid:=paid+amount; end loop; if paid+coalesce(p_pending_cents,0)<>total then raise exception 'A soma dos pagamentos e da pendência deve ser igual ao total dos produtos'; end if; if coalesce(p_pending_cents,0)>0 then insert into public.product_sale_receivables(sale_id,barbershop_id,unit_id,original_due_cents,paid_cents,status,due_date,note) values(s.id,s.barbershop_id,s.unit_id,p_pending_cents,0,'open',p_due_date,nullif(btrim(coalesce(p_note,'')),'')); end if; update public.product_sales set subtotal_cents=total,total_cents=total,cost_total_cents=cost_total,paid_cents=paid,pending_cents=coalesce(p_pending_cents,0),status='completed',completed_by_member_id=p_actor_member_id,completed_at=now(),updated_at=now(),note=coalesce(nullif(btrim(coalesce(p_note,'')),''),note) where id=s.id; return jsonb_build_object('ok',true,'sale_id',s.id,'total_cents',total,'paid_cents',paid,'pending_cents',coalesce(p_pending_cents,0)); end $$;
revoke all on function barberium.complete_product_sale_core(uuid,jsonb,integer,date,text,uuid) from public,anon,authenticated;

create or replace function public.barberium_staff_complete_product_sale(p_unit_id uuid,p_customer_id uuid,p_seller_professional_id uuid,p_items jsonb,p_payments jsonb,p_pending_cents integer default 0,p_due_date date default null,p_note text default null) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; perms jsonb; seller uuid; sale_id uuid; r jsonb; prod record; qty integer; v_unit uuid; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Sem acesso'; end if; perms:=case when m.role in ('owner','admin') then barberium.default_barber_permissions() else barberium.effective_permissions(m.professional_id) end; if m.role='barber' and not barberium.permission_enabled(perms,'sell_products') then raise exception 'Sem permissão para vender produtos'; end if; if m.role='barber' then select unit_id into v_unit from public.professionals where id=m.professional_id; if p_unit_id is not null and p_unit_id<>v_unit then raise exception 'Unidade inválida'; end if; seller:=m.professional_id; else v_unit:=p_unit_id; seller:=p_seller_professional_id; end if; if not exists(select 1 from public.units where id=v_unit and barbershop_id=m.barbershop_id and is_active) then raise exception 'Unidade inválida'; end if; if p_customer_id is not null and not exists(select 1 from public.customers where id=p_customer_id and barbershop_id=m.barbershop_id) then raise exception 'Cliente inválido'; end if; if seller is not null and not exists(select 1 from public.professionals where id=seller and barbershop_id=m.barbershop_id and unit_id=v_unit and is_active) then raise exception 'Profissional responsável inválido'; end if; if coalesce(p_pending_cents,0)>0 and m.role='barber' and not barberium.permission_enabled(perms,'leave_payment_pending') then raise exception 'Sem permissão para deixar pagamento pendente'; end if; insert into public.product_sales(barbershop_id,unit_id,customer_id,seller_professional_id,status,note,created_by_member_id) values(m.barbershop_id,v_unit,p_customer_id,seller,'draft',nullif(btrim(coalesce(p_note,'')),''),m.member_id) returning id into sale_id; for r in select * from jsonb_array_elements(coalesce(p_items,'[]'::jsonb)) loop qty:=coalesce((r->>'quantity')::int,0); if qty<=0 then continue; end if; select * into prod from public.products where id=(r->>'product_id')::uuid and barbershop_id=m.barbershop_id and is_active; if prod.id is null then raise exception 'Produto inválido'; end if; insert into public.product_sale_items(sale_id,product_id,product_name_snapshot,sku_snapshot,quantity,unit_price_cents,unit_cost_cents,line_total_cents) values(sale_id,prod.id,prod.name,prod.sku,qty,prod.price_cents,prod.cost_cents,prod.price_cents*qty); end loop; return barberium.complete_product_sale_core(sale_id,p_payments,coalesce(p_pending_cents,0),p_due_date,p_note,m.member_id); end $$;

create or replace function public.barberium_staff_product_sales(p_start date default (current_date-interval '30 days')::date,p_end date default current_date,p_unit_id uuid default null,p_customer_id uuid default null,p_limit integer default 100) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Sem acesso'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'status',x.status,'unit_id',x.unit_id,'unit',u.name,'customer_id',x.customer_id,'customer',c.full_name,'appointment_id',x.appointment_id,'seller_professional_id',x.seller_professional_id,'seller',pr.name,'total_cents',x.total_cents,'paid_cents',x.paid_cents,'pending_cents',x.pending_cents,'cost_total_cents',case when m.role in ('owner','admin') then x.cost_total_cents else null end,'completed_at',x.completed_at,'refunded_at',x.refunded_at,'items',coalesce((select sum(i.quantity) from public.product_sale_items i where i.sale_id=x.id),0)) order by x.completed_at desc) from (select * from public.product_sales s where s.barbershop_id=m.barbershop_id and s.status in ('completed','refunded') and s.completed_at::date between p_start and p_end and (p_unit_id is null or s.unit_id=p_unit_id) and (p_customer_id is null or s.customer_id=p_customer_id) and (m.role in ('owner','admin') or s.seller_professional_id=m.professional_id) order by s.completed_at desc limit greatest(1,least(coalesce(p_limit,100),500))) x join public.units u on u.id=x.unit_id left join public.customers c on c.id=x.customer_id left join public.professionals pr on pr.id=x.seller_professional_id),'[]'::jsonb); end $$;

create or replace function public.barberium_staff_product_sale_detail(p_sale_id uuid) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; s record; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Sem acesso'; end if; select * into s from public.product_sales where id=p_sale_id and barbershop_id=m.barbershop_id; if s.id is null or (m.role='barber' and s.seller_professional_id<>m.professional_id) then raise exception 'Venda inválida'; end if; return jsonb_build_object('id',s.id,'status',s.status,'unit_id',s.unit_id,'unit',(select name from public.units where id=s.unit_id),'customer_id',s.customer_id,'customer',(select full_name from public.customers where id=s.customer_id),'appointment_id',s.appointment_id,'seller_professional_id',s.seller_professional_id,'seller',(select name from public.professionals where id=s.seller_professional_id),'subtotal_cents',s.subtotal_cents,'total_cents',s.total_cents,'cost_total_cents',case when m.role in ('owner','admin') then s.cost_total_cents else null end,'paid_cents',s.paid_cents,'pending_cents',s.pending_cents,'note',s.note,'completed_at',s.completed_at,'refunded_at',s.refunded_at,'items',coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'product_id',i.product_id,'name',i.product_name_snapshot,'sku',i.sku_snapshot,'quantity',i.quantity,'unit_price_cents',i.unit_price_cents,'unit_cost_cents',case when m.role in ('owner','admin') then i.unit_cost_cents else null end,'line_total_cents',i.line_total_cents,'commission_percent',i.commission_percent,'commission_cents',i.commission_cents) order by i.created_at) from public.product_sale_items i where i.sale_id=s.id),'[]'::jsonb),'payments',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'method',p.method,'amount_cents',p.amount_cents,'fee_cents',p.fee_cents,'received_at',p.received_at,'installments',p.installments,'provider',(select name from public.payment_providers where id=p.provider_id)) order by p.received_at) from public.product_sale_payments p where p.sale_id=s.id),'[]'::jsonb),'receivable',(select jsonb_build_object('original_due_cents',r.original_due_cents,'paid_cents',r.paid_cents,'remaining_cents',greatest(0,r.original_due_cents-r.paid_cents),'status',r.status,'due_date',r.due_date,'note',r.note) from public.product_sale_receivables r where r.sale_id=s.id),'refund',(select jsonb_build_object('amount_cents',f.amount_cents,'reason',f.reason,'refund_method',f.refund_method,'created_at',f.created_at) from public.finance_refunds f where f.product_sale_id=s.id order by f.created_at desc limit 1)); end $$;

create or replace function public.barberium_staff_refund_product_sale(p_sale_id uuid,p_reason text,p_refund_method text default 'pix') returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; s record; i record; v_refund uuid; v_session uuid; paid integer; ce record; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null or m.role not in ('owner','admin') then raise exception 'Acesso somente para ADM'; end if; if btrim(coalesce(p_reason,''))='' then raise exception 'Motivo obrigatório'; end if; if p_refund_method not in ('pix','cash','debit','credit','transfer','other') then raise exception 'Forma de estorno inválida'; end if; select * into s from public.product_sales where id=p_sale_id and barbershop_id=m.barbershop_id for update; if s.id is null or s.status<>'completed' then raise exception 'Venda não disponível para estorno'; end if; for i in select * from public.product_sale_items where sale_id=s.id loop perform barberium.apply_product_stock_change(i.product_id,s.unit_id,i.quantity,'refund',p_reason,'product_sale_refund',s.id,m.member_id,i.unit_cost_cents); end loop; for ce in select * from public.commission_entries where source_type='product_sale' and source_id in (select id from public.product_sale_items where sale_id=s.id) and amount_cents<>0 loop insert into public.commission_entries(barbershop_id,unit_id,professional_id,appointment_id,source_type,source_id,description,base_cents,rate_percent,amount_cents,status) values(ce.barbershop_id,ce.unit_id,ce.professional_id,ce.appointment_id,'product_refund',s.id,'Estorno de comissão • venda de produto',-abs(ce.base_cents),ce.rate_percent,-abs(ce.amount_cents),'open'); end loop; paid:=coalesce((select sum(amount_cents) from public.product_sale_payments where sale_id=s.id),0); if paid>0 then insert into public.finance_refunds(barbershop_id,unit_id,appointment_id,product_sale_id,amount_cents,reason,actor_member_id,refund_method) values(s.barbershop_id,s.unit_id,s.appointment_id,s.id,paid,btrim(p_reason),m.member_id,p_refund_method) returning id into v_refund; if p_refund_method='cash' then select id into v_session from public.cash_sessions where unit_id=s.unit_id and barbershop_id=s.barbershop_id and status='open' order by opened_at desc limit 1; if v_session is null then raise exception 'Abra o caixa da unidade antes de fazer estorno em dinheiro'; end if; insert into public.cash_movements(cash_session_id,barbershop_id,unit_id,movement_type,amount_cents,reference_type,reference_id,note,actor_member_id) values(v_session,s.barbershop_id,s.unit_id,'refund',-paid,'product_refund',v_refund,'Estorno de venda de produtos',m.member_id); end if; end if; update public.product_sale_receivables set status='cancelled',updated_at=now() where sale_id=s.id and status<>'paid'; update public.product_sales set status='refunded',refunded_at=now(),updated_at=now() where id=s.id; return jsonb_build_object('ok',true,'sale_id',s.id,'refund_cents',paid,'refund_id',v_refund); end $$;

create or replace function public.barberium_staff_product_report(p_start date,p_end date,p_unit_id uuid default null) returns jsonb language plpgsql security definer set search_path='public','barberium','auth','pg_temp' as $$ declare m record; v_unit uuid; rev integer; refunds integer; cost integer; units_sold integer; sales_count integer; begin if auth.uid() is null then raise exception 'Não autenticado'; end if; select * into m from barberium.staff_membership(); if m.member_id is null then raise exception 'Sem acesso'; end if; if m.role='barber' then select unit_id into v_unit from public.professionals where id=m.professional_id; else v_unit:=p_unit_id; end if; select coalesce(sum(sp.amount_cents),0) into rev from public.product_sale_payments sp join public.product_sales s on s.id=sp.sale_id where sp.barbershop_id=m.barbershop_id and sp.received_at::date between p_start and p_end and (v_unit is null or sp.unit_id=v_unit) and (m.role in ('owner','admin') or s.seller_professional_id=m.professional_id); select coalesce(sum(fr.amount_cents),0) into refunds from public.finance_refunds fr join public.product_sales s on s.id=fr.product_sale_id where fr.barbershop_id=m.barbershop_id and fr.product_sale_id is not null and fr.created_at::date between p_start and p_end and (v_unit is null or fr.unit_id=v_unit) and (m.role in ('owner','admin') or s.seller_professional_id=m.professional_id); select coalesce(sum(i.quantity*i.unit_cost_cents),0),coalesce(sum(i.quantity),0),count(distinct s.id) into cost,units_sold,sales_count from public.product_sales s join public.product_sale_items i on i.sale_id=s.id where s.barbershop_id=m.barbershop_id and s.status='completed' and s.completed_at::date between p_start and p_end and (v_unit is null or s.unit_id=v_unit) and (m.role in ('owner','admin') or s.seller_professional_id=m.professional_id); return jsonb_build_object('start',p_start,'end',p_end,'revenue_cents',rev,'refunds_cents',refunds,'net_revenue_cents',rev-refunds,'cost_cents',case when m.role in ('owner','admin') then cost else null end,'gross_profit_estimate_cents',case when m.role in ('owner','admin') then (rev-refunds-cost) else null end,'units_sold',units_sold,'sales_count',sales_count,'low_stock',coalesce((select jsonb_agg(jsonb_build_object('product_id',p.id,'name',p.name,'quantity',coalesce(i.quantity,0),'min_stock',p.min_stock) order by coalesce(i.quantity,0),p.name) from public.products p left join public.product_inventory i on i.product_id=p.id and i.unit_id=coalesce(v_unit,(select id from public.units where barbershop_id=m.barbershop_id and is_active order by created_at limit 1)) where p.barbershop_id=m.barbershop_id and p.is_active and coalesce(i.quantity,0)<=p.min_stock),'[]'::jsonb),'top_products',coalesce((select jsonb_agg(jsonb_build_object('product_id',q.product_id,'name',q.name,'quantity',q.qty,'revenue_cents',q.revenue) order by q.revenue desc,q.qty desc) from (select i.product_id,max(i.product_name_snapshot) name,sum(i.quantity)::int qty,sum(i.line_total_cents)::int revenue from public.product_sales s join public.product_sale_items i on i.sale_id=s.id where s.barbershop_id=m.barbershop_id and s.status='completed' and s.completed_at::date between p_start and p_end and (v_unit is null or s.unit_id=v_unit) and (m.role in ('owner','admin') or s.seller_professional_id=m.professional_id) group by i.product_id order by revenue desc limit 10) q),'[]'::jsonb)); end $$;

