revoke all on function public.barberium_staff_complete_product_sale(uuid,uuid,uuid,jsonb,jsonb,integer,date,text) from public,anon; grant execute on function public.barberium_staff_complete_product_sale(uuid,uuid,uuid,jsonb,jsonb,integer,date,text) to authenticated,service_role;
revoke all on function public.barberium_staff_product_sales(date,date,uuid,uuid,integer) from public,anon; grant execute on function public.barberium_staff_product_sales(date,date,uuid,uuid,integer) to authenticated,service_role;
